public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;
    private readonly Dictionary<int, List<int>> _ratings = new();

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your day right with hearty morning meals", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Midday meals to keep you energized", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Satisfying evening recipes for the whole family", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats and indulgent delights", Icon = "🍰" },
            new() { Name = "Vegetarian", Description = "Plant-based recipes full of flavor", Icon = "🥦" },
            new() { Name = "Quick & Easy", Description = "Ready in 30 minutes or less", Icon = "⚡" }
        };

        _recipes = new List<Recipe>
        {
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = new() { "2 cups flour", "2 eggs", "1.5 cups milk", "2 tbsp sugar", "1 tsp baking powder", "Pinch of salt" },
                Steps = new() { "Mix dry ingredients in a bowl.", "Whisk eggs and milk together.", "Combine wet and dry ingredients until just mixed.", "Heat a non-stick pan over medium heat.", "Pour batter and cook until bubbles form, then flip.", "Serve with maple syrup and fresh berries." },
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = new() { "1 head romaine lettuce", "1/2 cup croutons", "1/4 cup parmesan cheese", "Caesar dressing", "Grilled chicken (optional)" },
                Steps = new() { "Wash and chop the romaine lettuce.", "Toss lettuce with Caesar dressing.", "Add croutons and shaved parmesan.", "Top with grilled chicken if desired.", "Serve immediately." },
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Ingredients = new() { "400g spaghetti", "500g ground beef", "1 onion, diced", "2 cloves garlic", "400g canned tomatoes", "2 tbsp tomato paste", "Italian herbs" },
                Steps = new() { "Cook spaghetti according to package directions.", "Brown the ground beef in a large pan.", "Add onion and garlic, cook until soft.", "Stir in canned tomatoes, paste, and herbs.", "Simmer for 20 minutes.", "Serve sauce over spaghetti with parmesan." },
                AverageRating = 4.8, RatingCount = 20
            },
            new()
            {
                Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts",
                Ingredients = new() { "200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "50g flour" },
                Steps = new() { "Preheat oven to 220°C (425°F).", "Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold chocolate mixture into eggs, then add flour.", "Pour into greased ramekins.", "Bake for 12 minutes — center should be soft.", "Invert onto plates and serve immediately." },
                AverageRating = 4.9, RatingCount = 15
            },
            new()
            {
                Id = 5, Title = "Vegetable Stir Fry", Category = "Vegetarian",
                Ingredients = new() { "1 bell pepper", "1 zucchini", "1 cup broccoli", "2 tbsp soy sauce", "1 tbsp sesame oil", "Rice for serving" },
                Steps = new() { "Slice all vegetables into bite-sized pieces.", "Heat sesame oil in a wok over high heat.", "Add vegetables and stir fry for 4-5 minutes.", "Add soy sauce and toss to coat.", "Serve over steamed rice." },
                AverageRating = 4.3, RatingCount = 6
            },
            new()
            {
                Id = 6, Title = "15-Minute Garlic Shrimp", Category = "Quick & Easy",
                Ingredients = new() { "500g shrimp, peeled", "4 cloves garlic, minced", "2 tbsp butter", "1 tbsp olive oil", "Lemon juice", "Fresh parsley" },
                Steps = new() { "Heat butter and oil in a skillet.", "Add garlic and cook for 30 seconds.", "Add shrimp in a single layer.", "Cook 2-3 minutes per side until pink.", "Squeeze lemon juice over top.", "Garnish with parsley and serve." },
                AverageRating = 4.6, RatingCount = 10
            }
        };
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public List<Recipe> GetAllRecipes() => _recipes;

    public void AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _recipes.Max(r => r.Id) + 1,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries).Select(i => i.Trim()).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries).Select(s => s.Trim()).ToList(),
            AverageRating = 0,
            RatingCount = 0
        };
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        var recipe = GetRecipeById(recipeId);
        if (recipe == null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        recipe.RatingCount = _ratings[recipeId].Count;
        recipe.AverageRating = Math.Round(_ratings[recipeId].Average(), 1);
    }
}

